  /**
   * 处理剧情数据（开发环境）
   */
  function processPlotData(data) {
    // 处理新格式的数据结构
    const plotList = data.plotList || [];

    // 转换为标准格式 - 每个剧情包含其所有步骤
    stories = plotList.map((plot, index) => {
      // 使用索引作为ID（因为新格式没有uniqueID）
      const plotId = index + 1;

      // 找到当前执行的步骤
      const currentStep = plot.steps?.find(step => step.isExecuted) || plot.steps?.[0] || {};

      return {
        id: plotId, // 使用索引+1作为ID
        title: plot.title,
        summary: plot.summary || '', // 新增：剧情摘要
        content: currentStep.event || '', // 当前步骤的事件作为内容
        steps: plot.steps || [],
        currentStepId: currentStep.stepId || '1',
        isExecuted: plot.steps?.some(step => step.isExecuted) || false,
      };
    });

    // 按ID排序
    stories.sort((a, b) => parseInt(a.id) - parseInt(b.id));

    // 设置currentPlot（来自数据源）
    const currentPlotData = data.currentPlot || {};
    currentPlot = currentPlotData.plotId ? String(currentPlotData.plotId) : '0'; // 新格式：plotId
    currentStepId = currentPlotData.stepId ? String(currentPlotData.stepId) : '1';

    console.log('📊 数据源currentPlot设置为：', currentPlot, 'stepId:', currentStepId);

    // 根据currentPlot设置当前剧情索引
    if (currentPlot !== '0') {
      const foundIndex = stories.findIndex(story => String(story.id) === String(currentPlot));
      if (foundIndex !== -1) {
        currentStoryIndex = foundIndex;
        // 同步当前剧情的currentStepId
        const currentStory = stories[currentStoryIndex];
        if (currentStory) {
          currentStory.currentStepId = currentStepId;
        }
        console.log(`✅ 找到数据源currentPlot ${currentPlot}，对应索引 ${foundIndex}，同步stepId: ${currentStepId}`);
      } else {
        currentStoryIndex = 0;
        console.warn(`⚠️ 数据源currentPlot ${currentPlot} 在剧情列表中未找到，使用索引 0`);
      }
    } else {
      currentStoryIndex = 0;
      console.log('🎭 数据源currentPlot为空，表示未开始任何剧情，即将调用updateDisplay显示未选择状态');
    }

    updateDisplay();
    updateSortButton(); // 初始化排序按钮状态
    console.log('🎬 剧情数据加载完成：');
    console.log('   - 总剧情数：', stories.length);
    console.log('   - 数据源currentPlot：', currentPlot);
    console.log('   - 当前stepId：', currentStepId);
    console.log('   - 初始显示索引：', currentStoryIndex);
    console.log('   - 初始显示剧情：', stories[currentStoryIndex]?.title || '无');
  }

  /**
   * 处理剧情数据（生产环境）
   */
  async function processPlotDataForProduction() {
    console.log('🏭 生产环境：处理剧情数据');

    // 检查是否有内联数据（构建后的版本）
    if (typeof window.plot_data !== 'undefined') {
