        if (retryCount === 0) {
          showProductionError('生产环境初始化失败', error.message);
        } else {
          // 重试失败，继续下一次重试
          throw error;
        }
      }
    } else {
      console.warn('⚠️ 生产环境：initProductionEnvironment 函数不可用');
      // 只有在首次加载时才显示错误（避免重试时重复显示）
      if (retryCount === 0) {
        showProductionError('生产环境配置错误', 'initProductionEnvironment 函数不可用，可能未正确加载 init.js');
      } else {
        // 重试失败，继续下一次重试
