    const trimmedText = text ? text.trim() : '';

    // 检查文本有效性，避免发送空内容
    if (!trimmedText || ['…', '...'].includes(trimmedText) || trimmedText.length === 0) return;

    // 检查SillyTavern环境并发送命令
    if (typeof triggerSlash === 'function') {
      triggerSlash(`/send ${trimmedText}|/trigger`);
    } else {
      console.log('SillyTavern environment not detected. Would send:', trimmedText);
    }
  };

  /**
   * 复制文本到酒馆对话框（不自动执行）
   * @param {string} text - 要复制的文本内容
   */
  const copyToTavernTextarea = text => {
    try {
      // 调用前text去除前后空格
      const trimmedText = text ? text.trim() : '';

      // 检查文本有效性，避免复制空内容
      if (!trimmedText || ['…', '...'].includes(trimmedText) || trimmedText.length === 0) {
        console.warn('❌ 文本内容为空，无法复制');
        showFeedback('文本内容为空，无法复制');
        return false;
      }

      // 使用jQuery获取父页面的元素（当前页面是iframe）
      const $parentTextarea = window.parent.$('#send_textarea');

      if ($parentTextarea.length === 0) {
        console.error('❌ 无法找到父页面的 #send_textarea 元素');
        showFeedback('无法找到酒馆对话框，请确认页面已正确加载');
        return false;
      }

      // 获取当前输入框的值
      const currentValue = $parentTextarea.val() || '';

      // 将文本追加到输入框（不是替换）
      const newValue = currentValue ? `${currentValue}\n${trimmedText}` : trimmedText;
      $parentTextarea.val(newValue);

      console.log('✅ 文本已复制到酒馆对话框');
      console.log('📝 复制的内容:', trimmedText);

      return true;
    } catch (error) {
      console.error('❌ 复制到酒馆对话框时出错:', error);
      showFeedback(`复制失败: ${error.message}`);
      return false;
    }
  };

  /**
   * 获取当前剧情信息（供外部调用）
   */
  window.getCurrentStory = function () {
    return stories[currentStoryIndex];
  };

  /**
   * 跳转到指定剧情（供外部调用）
   */
  window.goToStory = function (index) {
    if (index >= 0 && index < stories.length) {
      currentStoryIndex = index;
      updateDisplay();
      return true;
    }
    return false;
  };

  /**
   * 设置剧情数据（供外部调用）
   */
  window.setStoryData = function (newStories) {
    if (Array.isArray(newStories) && newStories.length > 0) {
      stories = newStories;
      currentStoryIndex = 0;
      updateDisplay();
      return true;
    }
    return false;
  };

  /**
   * 获取当前步骤信息（供外部调用）
   */
  window.getCurrentStep = function () {
    const story = stories[currentStoryIndex];
    if (!story) return null;

    return {
      story: story.title,
      stepId: story.currentStepId,
      step: getCurrentStepInfo(story, story.currentStepId),
      totalSteps: story.steps?.length || 0,
    };
  };

  /**
   * 暴露 triggerQuickReply 函数到全局作用域（供外部调用）
   */
  window.triggerQuickReply = triggerQuickReply;

  /**
   * 暴露 checkEnvironment 函数到全局作用域（供外部调用）
   */
  window.checkEnvironment = checkEnvironment;

  // 初始化插件
  initStoryAssistant();

  console.log('剧情小助手初始化完成');
});


    </script>
